    fn test_fir_highpass_creation() {
        let fir = Fir::highpass(51, 1000.0, 48000.0, WindowType::Hann, 0.0);
        assert_eq!(fir.filter_type, FirFilterType::Highpass);
        assert_eq!(fir.n_taps(), 51);
        assert_eq!(fir.freq, 1000.0);
    }

